      { k: 'write', t: 'العلومُ والكتابة: الكتابةُ الوصفيّة', pg: '٧٤', x: 'أختارُ حيوانًا فقاريًّا منَ الحيواناتِ التي تعيشُ في منطقتي. أكتبُ فقرةً أوضّحُ فيها نوعَ هذا الحيوانِ وأصفُ بعضَ خصائصِه.' },
      { k: 'math', t: 'العلومُ والرياضيّات: كتلةُ الحوتِ الأزرق', pg: '٧٤', x: 'إذا كانتْ كتلةُ الحوتِ الأزرقِ حوالَيْ ١٠٠ طنّ، فما كتلتُه بالكيلوجرامات؟', a: '١٠٠ طنّ = ١٠٠٬٠٠٠ كجم (الطنُّ الواحدُ = ١٠٠٠ كجم).' },
      { k: 'table', t: 'الحيواناتُ المهدّدةُ بالانقراضِ في منطقةِ الدراسة', pg: '٧٥', x: 'حمايةُ الحيوانات: يحاولُ العلماءُ حمايةَ بعضِ الحيواناتِ المهدّدةِ بالانقراض، وذلكَ منْ خلالِ المؤسّساتِ والجمعيّاتِ المهتمّةِ بالحفاظِ على الحياةِ الفطريّة. وقدْ قامتْ إحدى جمعيّاتِ حمايةِ الحياةِ الفطريّةِ بحصرِ أعدادِ الحيواناتِ المهدّدةِ بالانقراضِ في منطقةٍ ما منَ العالم، ولخّصتْ نتائجَ الدراسةِ في الجدولِ التالي.', head: ['مجموعةُ الحيوان', 'عددُ الأنواعِ المهدّدةِ بالانقراض'], rows: [['الثدييّات', '٦٨'], ['الطيور', '٧٦'], ['الزواحف', '١٤'], ['البرمائيّات', '١٣'], ['الأسماك', '٧٥'], ['الحشراتُ والعناكب', '٥٩'], ['لافقاريّاتٌ أخرى', '١٠٥'], ['المجموع', '٤١٠']], img: 'houbara' },
      { k: 'math', t: 'أحلّ (١): اللافقاريّاتُ المهدّدة', pg: '٧٥', x: 'ما عددُ اللافقاريّاتِ المهدّدةِ بالانقراضِ في هذه المنطقة؟', a: '٥٩ + ١٠٥ = ١٦٤' },
      { k: 'math', t: 'أحلّ (٢): الفقاريّاتُ المهدّدة', pg: '٧٥', x: 'ما عددُ الفقاريّاتِ المهدّدةِ بالانقراضِ في هذه المنطقة؟', a: '٦٨ + ٧٦ + ١٤ + ١٣ + ٧٥ = ٢٤٦' },
      { k: 'math', t: 'أحلّ (٣): ترتيبُ الفقاريّات', pg: '٧٥', x: 'أرتّبُ أنواعَ الفقاريّاتِ المهدّدةِ بالانقراضِ بحسبِ أعدادِها منَ الأكثرِ إلى الأقلّ.', a: 'الطيور (٧٦)، ثمَّ الأسماك (٧٥)، ثمَّ الثدييّات (٦٨)، ثمَّ الزواحف (١٤)، ثمَّ البرمائيّات (١٣).' },
      { k: 'fact', t: 'الرابطُ معَ رؤية ٢٠٣٠', pg: '٧٥', x: 'منْ أهدافِ الرؤية: حمايةُ وتهيئةُ المناطقِ الطبيعيّة (مثلَ الشواطئِ والجزرِ والمحميّاتِ الطبيعيّة). الحُبارى طائرٌ مهدّدٌ بالانقراض.', img: 'houbara' }
